package br.com.onda;
import android.provider.*;import android.content.*;import android.net.Uri;import android.content.ContentValues;import android.database.*;import android.os.*;import java.io.*;import java.util.*;
/** Test APK only: a DocumentsContract-compatible fixture backed by isolated real files. */
public class BatchTestDocumentsProvider extends ContentProvider {
 private File root(){File root=new File(getContext().getFilesDir(),"chapter-batch-test");root.mkdirs();return root;}
 private File file(String id)throws FileNotFoundException{try{File root=root().getCanonicalFile(),file="root".equals(id)?root:new File(root,id.substring(5)).getCanonicalFile();if(!id.equals("root")&&!id.startsWith("root/"))throw new IOException();if(!file.equals(root)&&!file.getPath().startsWith(root.getPath()+File.separator))throw new IOException();return file;}catch(Exception e){throw new FileNotFoundException("Invalid test document");}}
 private String id(File file){String base=root().getAbsolutePath();return file.getAbsolutePath().equals(base)?"root":"root/"+file.getAbsolutePath().substring(base.length()+1);}
 private final String[] columns={DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_SIZE,DocumentsContract.Document.COLUMN_LAST_MODIFIED,DocumentsContract.Document.COLUMN_FLAGS};
 private void row(MatrixCursor cursor,File f){MatrixCursor.RowBuilder row=cursor.newRow();for(String column:cursor.getColumnNames()){Object value=null;if(column.equals(DocumentsContract.Document.COLUMN_DOCUMENT_ID))value=id(f);else if(column.equals(DocumentsContract.Document.COLUMN_DISPLAY_NAME))value=f.equals(root())?"Batch test storage":f.getName();else if(column.equals(DocumentsContract.Document.COLUMN_MIME_TYPE))value=f.isDirectory()?DocumentsContract.Document.MIME_TYPE_DIR:"audio/mpeg";else if(column.equals(DocumentsContract.Document.COLUMN_SIZE))value=f.length();else if(column.equals(DocumentsContract.Document.COLUMN_LAST_MODIFIED))value=f.lastModified();else if(column.equals(DocumentsContract.Document.COLUMN_FLAGS))value=f.isDirectory()?DocumentsContract.Document.FLAG_DIR_SUPPORTS_CREATE|DocumentsContract.Document.FLAG_SUPPORTS_DELETE:DocumentsContract.Document.FLAG_SUPPORTS_WRITE|DocumentsContract.Document.FLAG_SUPPORTS_DELETE;row.add(value);}}
 @Override public boolean onCreate(){return true;}
 public Cursor queryRoots(String[] projection){String[] names=projection==null?new String[]{DocumentsContract.Root.COLUMN_ROOT_ID,DocumentsContract.Root.COLUMN_DOCUMENT_ID,DocumentsContract.Root.COLUMN_TITLE,DocumentsContract.Root.COLUMN_FLAGS}:projection;MatrixCursor cursor=new MatrixCursor(names);MatrixCursor.RowBuilder row=cursor.newRow();for(String name:names)row.add(name.equals(DocumentsContract.Root.COLUMN_ROOT_ID)?"batch":name.equals(DocumentsContract.Root.COLUMN_DOCUMENT_ID)?"root":name.equals(DocumentsContract.Root.COLUMN_TITLE)?"Batch tests":name.equals(DocumentsContract.Root.COLUMN_FLAGS)?DocumentsContract.Root.FLAG_SUPPORTS_CREATE|DocumentsContract.Root.FLAG_SUPPORTS_IS_CHILD:null);return cursor;}
 public Cursor queryDocument(String documentId,String[] projection)throws FileNotFoundException{File file=file(documentId);if(!file.exists())throw new FileNotFoundException();MatrixCursor cursor=new MatrixCursor(projection==null?columns:projection);row(cursor,file);return cursor;}
 public Cursor queryChildDocuments(String documentId,String[] projection,String sort)throws FileNotFoundException{MatrixCursor cursor=new MatrixCursor(projection==null?columns:projection);File[] files=file(documentId).listFiles();if(files!=null){Arrays.sort(files,Comparator.comparing(File::getName));for(File file:files)row(cursor,file);}return cursor;}
 public ParcelFileDescriptor openDocument(String documentId,String mode,CancellationSignal cancel)throws FileNotFoundException{return ParcelFileDescriptor.open(file(documentId),ParcelFileDescriptor.parseMode(mode));}
 public String createDocument(String parent,String mime,String name)throws FileNotFoundException{File directory=file(parent);name=name.replace('/','_').replace('\\','_');File target=new File(directory,name);int n=2;while(target.exists())target=new File(directory,name+" ("+(n++)+")");boolean made=DocumentsContract.Document.MIME_TYPE_DIR.equals(mime)?target.mkdir():create(target);if(!made)throw new FileNotFoundException("Cannot create test document");return id(target);}
 private boolean create(File file){try{return file.createNewFile();}catch(IOException e){return false;}}
 public void deleteDocument(String id)throws FileNotFoundException{remove(file(id));}
 private void remove(File file){File[] files=file.listFiles();if(files!=null)for(File child:files)remove(child);file.delete();}
 public boolean isChildDocument(String parent,String child){try{return file(child).getPath().startsWith(file(parent).getPath()+File.separator);}catch(Exception e){return false;}}
 @Override public Cursor query(Uri uri,String[] projection,String selection,String[] args,String sort){try{if(uri.getPath().endsWith("/children"))return queryChildDocuments(DocumentsContract.getDocumentId(uri),projection,sort);if(uri.getPath().contains("/document/"))return queryDocument(DocumentsContract.getDocumentId(uri),projection);return queryRoots(projection);}catch(FileNotFoundException e){return new MatrixCursor(projection==null?columns:projection);}}
 @Override public String getType(Uri uri){try{return file(DocumentsContract.getDocumentId(uri)).isDirectory()?DocumentsContract.Document.MIME_TYPE_DIR:"audio/mpeg";}catch(Exception e){return DocumentsContract.Document.MIME_TYPE_DIR;}}
 @Override public ParcelFileDescriptor openFile(Uri uri,String mode)throws FileNotFoundException{return openDocument(DocumentsContract.getDocumentId(uri),mode,null);}
 @Override public Uri insert(Uri uri,ContentValues values){throw new UnsupportedOperationException();}
 @Override public int update(Uri uri,ContentValues values,String selection,String[] args){throw new UnsupportedOperationException();}
 @Override public int delete(Uri uri,String selection,String[] args){try{deleteDocument(DocumentsContract.getDocumentId(uri));return 1;}catch(Exception e){return 0;}}
 @Override public Bundle call(String method,String arg,Bundle extras){try{Uri uri=extras.getParcelable("uri");Bundle result=new Bundle();if("android:createDocument".equals(method)){String id=createDocument(DocumentsContract.getDocumentId(uri),extras.getString(DocumentsContract.Document.COLUMN_MIME_TYPE),extras.getString(DocumentsContract.Document.COLUMN_DISPLAY_NAME));result.putParcelable("uri",DocumentsContract.buildDocumentUriUsingTree(uri,id));return result;}if("android:deleteDocument".equals(method)){deleteDocument(DocumentsContract.getDocumentId(uri));return result;}if("android:isChildDocument".equals(method)){Uri target=extras.getParcelable("android.content.extra.TARGET_URI");result.putBoolean("result",isChildDocument(DocumentsContract.getDocumentId(uri),DocumentsContract.getDocumentId(target)));return result;}return super.call(method,arg,extras);}catch(FileNotFoundException e){throw new IllegalArgumentException(e);}}
}
